def field(label,kind='text',wide=False,options=None,autocomplete=None,required=True):
 attr=' required' if required else '';name='email' if label=='Email' else H(label);klass='field wide' if wide else 'field';ac=f' autocomplete="{autocomplete}"' if autocomplete else ''
 if options:control=f'<select name="{name}"{attr}><option value="">Select an option</option>'+''.join(f'<option>{H(o)}</option>' for o in options)+'</select>'
 elif kind=='textarea':control=f'<textarea name="{name}" rows="5" maxlength="2000"{attr}></textarea>'
 else:control=f'<input type="{kind}" name="{name}" maxlength="150"{ac}{attr}>'
 return f'<label class="{klass}">{H(label)}{" *" if required else ""}{control}</label>'
