# Every page shares the same accessible scroll-reveal enhancement.
for page in D.rglob('index.html'):
 text=re.sub(r'<script src="/scroll-reveal\.js(?:\?[^"]*)?" defer></script>', '', page.read_text())
 text=text.replace('</head>', '<script src="/scroll-reveal.js?v=2" defer></script></head>')
 page.write_text(text)

# Shared cart and on-site checkout.
for page in D.rglob('index.html'):
 text=page.read_text()
 if '/cart.js' not in text:
  text=text.replace('</head>', '<link rel="stylesheet" href="/cart.css?v=1"><script src="/cart.js?v=1" defer></script></head>')
 page.write_text(text)
